mapper.update:
update book
set stock_quantity = stock_quantity + #{delta}
where id = #{id} and stock_quantity + #{delta} >= 0

mapper.select:
select * from book
and (book_title like concat('%', #{keyword}, '%') or author like concat('%', #{keyword}, '%') or isbn like concat('%', #{keyword}, '%'))
order by id desc limit #{limit} offset #{offset}
